Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '..\Common.ps1')
. (Join-Path $PSScriptRoot '..\Funnel.Common.ps1')
. (Join-Path $PSScriptRoot '..\Ngrok.Common.ps1')
$passed=0;$failed=0
function Run([string]$Name,[scriptblock]$Action){try{&$Action;$script:passed++;"PASS $Name"}catch{$script:failed++;"FAIL $Name : $($_.Exception.Message)"}}
function Reject([scriptblock]$Action){try{&$Action|Out-Null}catch{return};throw 'Hostile fixture was accepted.'}
$root=Join-Path ([IO.Path]::GetTempPath()) "aevrynd-ngrok-tests-$([Guid]::NewGuid().ToString('N'))";New-Item -ItemType Directory $root|Out-Null;$paths=@{State=$root;NgrokStateFile=(Join-Path $root 'ngrok-state.json');NgrokPendingFile=(Join-Path $root 'ngrok-pending.json');NgrokDomainFile=(Join-Path $root 'ngrok-domain.json')}
try{
 Run 'accept exact assigned free development domain' {[IO.File]::WriteAllText($paths.NgrokDomainFile,'{"schemaVersion":1,"domain":"sample-cupid-overdrawn.ngrok-free.dev"}');$value=Read-NgrokDomainConfiguration $paths;if($value.WebhookUrl-cne'https://sample-cupid-overdrawn.ngrok-free.dev/webhook'){throw 'Wrong webhook URL.'}}
 foreach($json in @('{"schemaVersion":"1","domain":"sample-cupid-overdrawn.ngrok-free.dev"}','{"schemaVersion":true,"domain":"sample-cupid-overdrawn.ngrok-free.dev"}','{"schemaVersion":1,"domain":"*.ngrok-free.dev"}','{"schemaVersion":1,"domain":"https://sample-cupid-overdrawn.ngrok-free.dev"}','{"schemaVersion":1,"domain":"sample-cupid-overdrawn.ngrok-free.dev.evil.test"}','{"schemaVersion":1,"domain":"Sample-cupid-overdrawn.ngrok-free.dev"}','{"schemaVersion":1,"domain":"sample-cupid-overdrawn.ngrok-free.dev","extra":1}','{"schemaVersion":1,"schemaVersion":1,"domain":"sample-cupid-overdrawn.ngrok-free.dev"}')){Run "reject hostile fixture $json" {[IO.File]::WriteAllText($paths.NgrokDomainFile,$json);Reject {Read-NgrokDomainConfiguration $paths}}}
 Run 'credential setter forbids token command-line parameter and plaintext config' {$content=Get-Content -Raw (Join-Path $PSScriptRoot '..\Set-NgrokCredential.ps1');if($content-match'param\([^)]*(Token|Authtoken)'-or$content-match'config add-authtoken'){throw 'Credential setter exposes a plaintext token path.'};if(-not$content.Contains('Read-Host')-or-not$content.Contains('ZeroFreeCoTaskMemUnicode')){throw 'Credential secure input lifecycle is missing.'}}
 Run 'start provider uses exact origin domain scheme and disables inspection' {$content=Get-Content -Raw (Join-Path $PSScriptRoot '..\Start-Ngrok.ps1');foreach($required in @("'http://127.0.0.1:8787'",'--domain=','--scheme=https','--inspect=false','--log=false','NGROK_AUTHTOKEN','/not-webhook')){if(-not$content.Contains($required)){throw "Start provider lacks fixed control: $required"}};foreach($forbidden in @('--authtoken','config add-authtoken','0.0.0.0')){if($content.Contains($forbidden)){throw "Start provider contains forbidden token or bind control: $forbidden"}}}
 Run 'startup and discovery include mutually exclusive ngrok provider' {$startup=Get-Content -Raw (Join-Path $PSScriptRoot '..\Register-Startup.ps1');$discover=Get-Content -Raw (Join-Path $PSScriptRoot '..\Discover-Allowlist.ps1');if(-not$startup.Contains("'None','Cloudflare','Funnel','Ngrok'")-or-not$startup.Contains('Aevrynd-Line-Gateway-Ngrok')){throw 'AtLogOn ngrok task is missing.'};if(-not$discover.Contains('Test-NgrokConfiguration.ps1')-or-not$discover.Contains('$ngrokActive')){throw 'Enrollment transport exclusivity lacks ngrok.'}}
 Run 'plaintext migration requires explicit rotation confirmation and creates no backup' {$content=Get-Content -Raw (Join-Path $PSScriptRoot '..\Remove-NgrokPlaintextCredential.ps1');if(-not$content.Contains('ConfirmRotated')-or-not$content.Contains('Rotate the exposed authtoken')){throw 'Rotation gate is missing.'};if($content-match'(?m)^\s*(Copy-Item|Move-Item)\b|\[IO\.File\]::WriteAllText'){throw 'Plaintext migration may preserve a secret copy.'}}
 Run 'state round trip is exact and atomic' {$stamp=[DateTimeOffset]::UtcNow.ToString('o');Write-NgrokState $paths 123 $stamp 'sample-cupid-overdrawn.ngrok-free.dev' 'C:\Program Files\WindowsApps\ngrok.exe' ('a'*64);$state=Read-NgrokState $paths;if($state.pid-ne123-or$state.startedUtc-cne$stamp){throw 'State round trip failed.'};if(@(Get-ChildItem $root|Where-Object{$_.Name-like'ngrok-state.json.*'}).Count){throw 'Atomic state artifacts remain.'}}
 foreach($bad in @(
  '{"schemaVersion":"1","pid":123,"startedUtc":"STAMP","domain":"sample-cupid-overdrawn.ngrok-free.dev","executablePath":"C:\\\\ngrok.exe","executableSha256":"HASH","origin":"http://127.0.0.1:8787","path":"/webhook"}',
  '{"schemaVersion":1,"pid":true,"startedUtc":"STAMP","domain":"sample-cupid-overdrawn.ngrok-free.dev","executablePath":"C:\\\\ngrok.exe","executableSha256":"HASH","origin":"http://127.0.0.1:8787","path":"/webhook"}',
  '{"schemaVersion":1,"pid":123,"startedUtc":"STAMP","domain":"sample-cupid-overdrawn.ngrok-free.dev","executablePath":"C:\\\\ngrok.exe","executableSha256":"HASH","origin":"http://evil.test","path":"/webhook"}',
  '{"schemaVersion":1,"pid":123,"startedUtc":"STAMP","domain":"sample-cupid-overdrawn.ngrok-free.dev","executablePath":"C:\\\\ngrok.exe","executableSha256":"HASH","origin":"http://127.0.0.1:8787","path":"/webhook","extra":1}'
 )){Run 'reject hostile runtime state' {$json=$bad.Replace('STAMP',[DateTimeOffset]::UtcNow.ToString('o')).Replace('HASH',('b'*64));[IO.File]::WriteAllText($paths.NgrokStateFile,$json);Reject {Read-NgrokState $paths}}}
 Run 'stop and test consume only closed runtime state' {$stop=Get-Content -Raw (Join-Path $PSScriptRoot '..\Stop-Ngrok.ps1');$test=Get-Content -Raw (Join-Path $PSScriptRoot '..\Test-NgrokConfiguration.ps1');if(-not$stop.Contains('Read-NgrokState')-or-not$test.Contains('Read-NgrokState')){throw 'Runtime consumers bypass closed state parsing.'};if($stop-match'Get-Content.+NgrokStateFile|ConvertFrom-Json'){throw 'Stop uses weak state parsing.'}}
 Run 'exact command line rejects injection reorder and alternate origin' {$exe='C:\Program Files\WindowsApps\ngrok.exe';$domain='sample-cupid-overdrawn.ngrok-free.dev';$valid='"'+$exe+'" http http://127.0.0.1:8787 --domain='+$domain+' --scheme=https --inspect=false --log=false --web-addr=127.0.0.1:4040';if(-not(Test-ExactNgrokCommandLine $valid $exe $domain)){throw 'Exact command was rejected.'};foreach($bad in @($valid+' --extra',$valid.Replace('127.0.0.1:8787','127.0.0.1:9999'),$valid.Replace('--scheme=https --inspect=false','--inspect=false --scheme=https'))){if(Test-ExactNgrokCommandLine $bad $exe $domain){throw 'Hostile command was accepted.'}}}
 Run 'live executable handle blocks replacement during identity validation' {$file=Join-Path $root 'fake-ngrok.exe';[IO.File]::WriteAllBytes($file,[byte[]](1,2,3));$stream=[IO.FileStream]::new($file,'Open','Read','Read');try{$blocked=$false;try{Remove-Item $file -Force}catch{$blocked=$true};if(-not$blocked){throw 'Executable replacement was not blocked.'};if([Aevrynd.SafePath]::FinalPath($stream.SafeFileHandle)-cne[IO.Path]::GetFullPath($file)){throw 'Handle identity failed.'}}finally{$stream.Dispose()}}
 Run 'runtime consumers require exact command and live executable identity' {$stop=Get-Content -Raw (Join-Path $PSScriptRoot '..\Stop-Ngrok.ps1');$test=Get-Content -Raw (Join-Path $PSScriptRoot '..\Test-NgrokConfiguration.ps1');foreach($content in @($stop,$test)){foreach($required in @('Get-NgrokExecutableIdentity','Assert-NgrokProcessIdentity','.Stream.Dispose()')){if(-not$content.Contains($required)){throw "Runtime consumer lacks $required"}}}}
 Run 'fake process accepts exact tuple and rejects command injection' {$file=Join-Path $root 'controlled-ngrok.exe';[IO.File]::WriteAllBytes($file,[byte[]](4,5,6));$stream=[IO.FileStream]::new($file,'Open','Read','Read');$start=[DateTime]::UtcNow;$domain='sample-cupid-overdrawn.ngrok-free.dev';$script:fakeCommand='"'+$file+'" http http://127.0.0.1:8787 --domain='+$domain+' --scheme=https --inspect=false --log=false --web-addr=127.0.0.1:4040';$script:fakeProcess=[pscustomobject]@{Path=$file;StartTime=$start};function global:Get-CimInstance{[pscustomobject]@{CommandLine=$script:fakeCommand}};function global:Get-Process{$script:fakeProcess};try{$identity=[pscustomobject]@{Path=$file;Sha256=('c'*64);Stream=$stream};$state=[pscustomobject]@{pid=42;startedUtc=$start.ToUniversalTime().ToString('o');domain=$domain;executablePath=$file;executableSha256=('c'*64)};$result=Assert-NgrokProcessIdentity $state $identity;if($result.Path-cne$file){throw 'Exact fake process was rejected.'};$script:fakeCommand+=' --extra';Reject {Assert-NgrokProcessIdentity $state $identity}}finally{$stream.Dispose();Remove-Item Function:\global:Get-CimInstance,Function:\global:Get-Process -ErrorAction SilentlyContinue}}
 Run 'plaintext cleanup scans bounded bytes zeroizes and deletes by verified handle' {$content=Get-Content -Raw (Join-Path $PSScriptRoot '..\Remove-NgrokPlaintextCredential.ps1');foreach($required in @('Enter-PublicTransportLock','Open-VerifiedDirectoryHandle',"'None'",'65536','[Array]::Clear','SetLength(0)','Flush($true)','SetFileInformationByHandle','DeleteOnClose($stream.SafeFileHandle)')){if(-not$content.Contains($required)){throw "Cleanup lacks $required"}};foreach($forbidden in @('ReadAllText','Get-Content','ReadToEnd','Remove-Item -LiteralPath $path')){if($content.Contains($forbidden)){throw "Cleanup materializes or deletes plaintext by unsafe path through $forbidden"}}}
 Run 'pending state exists before launch and clears only after durable active state' {$start=Get-Content -Raw (Join-Path $PSScriptRoot '..\Start-Ngrok.ps1');$write=$start.IndexOf('Write-NgrokPendingState');$launch=$start.IndexOf('[AevryndNgrokLauncher]::Start');$active=$start.IndexOf('Write-NgrokState');$clear=$start.LastIndexOf('Remove-Item -LiteralPath $paths.NgrokPendingFile');if($write-lt0-or$launch-lt$write-or$active-lt$launch-or$clear-lt$active){throw 'Launch journal ordering is unsafe.'}}
 Run 'pending crash with no process is safely cleared' {$fake=Join-Path $root 'ngrok.exe';[IO.File]::WriteAllBytes($fake,[byte[]](7,8));$stream=[IO.FileStream]::new($fake,'Open','Read','Read');$identity=[pscustomobject]@{Path=$fake;Sha256=('d'*64);Stream=$stream};function global:Get-CimInstance{return @()};try{Write-NgrokPendingState $paths 'sample-cupid-overdrawn.ngrok-free.dev' $identity ([Guid]::NewGuid().ToString('N'));Resolve-NgrokPendingLaunch $paths $identity;if(Test-Path $paths.NgrokPendingFile){throw 'Pending state remained.'}}finally{$stream.Dispose();Remove-Item Function:\global:Get-CimInstance -ErrorAction SilentlyContinue}}
 Run 'trusted bootstrap is closed handle-bound and scheduler-only' {$bootstrap=Get-Content -Raw (Join-Path $PSScriptRoot '..\Bootstrap.ps1');$register=Get-Content -Raw (Join-Path $PSScriptRoot '..\Register-Startup.ps1');foreach($required in @('ValidateSet(''Gateway'',''Ngrok'',''Cloudflare'')','Assert-ProtectedDirectory','GetFinalPathNameByHandle','Read-HeldBytes','Bootstrap self identity differs from manifest','Bootstrap target hash differs from manifest')){if(-not$bootstrap.Contains($required)){throw "Bootstrap lacks $required"}};if($bootstrap-match'(?m)^\s*\.\s+'){throw 'Bootstrap dot-sources untrusted code.'};if($register-match'-File\s+`"\$[^`"]*(Start-Gateway|Start-Ngrok|Start-Tunnel)'){throw 'Scheduler bypasses bootstrap.'};if(-not$register.Contains('-Entry Gateway')-or-not$register.Contains('-Entry Ngrok')-or-not$register.Contains('-Entry Cloudflare')){throw 'Scheduler closed dispatch is incomplete.'}}
 Run 'bootstrap ACL mask accepts read and rejects primitive mutation rights' {$bootstrap=Get-Content -Raw (Join-Path $PSScriptRoot '..\Bootstrap.ps1');foreach($right in @('WriteData','AppendData','WriteExtendedAttributes','WriteAttributes','Delete','DeleteSubdirectoriesAndFiles','ChangePermissions','TakeOwnership')){if(-not$bootstrap.Contains("FileSystemRights]::$right")){throw "ACL mask lacks $right"}};if($bootstrap-match'FileSystemRights]::(Modify|FullControl).*\$mutation'){throw 'ACL mutation mask uses a composite right.'};$read=[Security.AccessControl.FileSystemRights]'ReadAndExecute, Synchronize';$mutation=[Security.AccessControl.FileSystemRights]::WriteData-bor[Security.AccessControl.FileSystemRights]::AppendData-bor[Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles;if(($read-band$mutation)-ne0){throw 'Read-only fixture was rejected.'};foreach($hostile in @([Security.AccessControl.FileSystemRights]::WriteData,[Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles)){if(($hostile-band$mutation)-eq0){throw 'Mutation fixture was accepted.'}}}
 Run 'installer root ACL removes user delete-child and grants only explicit mutable children' {$install=Get-Content -Raw (Join-Path $PSScriptRoot '..\Install.ps1');if(-not$install.Contains('$rootCurrentIdentity, [Security.AccessControl.FileSystemRights]''ReadAndExecute, Synchronize''')-or-not$install.Contains('$mutableSecurity.SetAccessRuleProtection($true,$false)')){throw 'Installer root/mutable ACL split is absent.'};foreach($child in @('$paths.Config','$paths.Data','$paths.Logs','$paths.State',"Join-Path `$paths.Root 'handoff'","Join-Path `$paths.Root 'cloudflared'","Join-Path `$paths.Root 'staging'")){if(-not$install.Contains($child)){throw "Mutable ACL child missing: $child"}}}
}finally{if(Test-Path $root){Remove-Item $root -Recurse -Force}}
if($failed){throw "$failed ngrok tests failed; $passed passed."};"Ngrok foundation tests passed ($passed/$passed)."
